-- Protect the public AI bridge across Vercel instances and cap daily free-tier usage.
-- Client identifiers are HMACs generated by the server; raw IPs are never stored.
alter table public.public_endpoint_rate_limits
  drop constraint if exists public_endpoint_rate_limits_route_name_check;

alter table public.public_endpoint_rate_limits
  add constraint public_endpoint_rate_limits_route_name_check
  check (route_name in ('gdelt', 'market-assist'));

create or replace function public.consume_public_endpoint_rate_limit(
  p_route_name text,
  p_client_hash text,
  p_global_hash text
)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now timestamptz := clock_timestamp();
  v_client_minute integer;
  v_global_minute integer;
  v_client_day integer;
  v_global_day integer;
begin
  if p_route_name not in ('gdelt', 'market-assist')
    or p_client_hash !~ '^[a-f0-9]{64}$'
    or p_global_hash !~ '^[a-f0-9]{64}$' then
    return false;
  end if;

  insert into public.public_endpoint_rate_limits as current_limit
    (route_name, bucket_kind, bucket_hash, window_started_at, attempts)
  values (p_route_name, 'client', p_client_hash, v_now, 1)
  on conflict (route_name, bucket_kind, bucket_hash) do update set
    window_started_at = case
      when current_limit.window_started_at <= v_now - interval '1 minute' then v_now
      else current_limit.window_started_at
    end,
    attempts = case
      when current_limit.window_started_at <= v_now - interval '1 minute' then 1
      else least(current_limit.attempts + 1, 61)
    end
  returning attempts into v_client_minute;

  insert into public.public_endpoint_rate_limits as current_limit
    (route_name, bucket_kind, bucket_hash, window_started_at, attempts)
  values (p_route_name, 'global', p_global_hash, v_now, 1)
  on conflict (route_name, bucket_kind, bucket_hash) do update set
    window_started_at = case
      when current_limit.window_started_at <= v_now - interval '1 minute' then v_now
      else current_limit.window_started_at
    end,
    attempts = case
      when current_limit.window_started_at <= v_now - interval '1 minute' then 1
      else least(current_limit.attempts + 1, 31)
    end
  returning attempts into v_global_minute;

  if p_route_name = 'gdelt' then
    delete from public.public_endpoint_rate_limits
      where window_started_at < v_now - interval '2 days';
    return v_client_minute <= 10 and v_global_minute <= 30;
  end if;

  insert into public.public_endpoint_rate_limits as current_limit
    (route_name, bucket_kind, bucket_hash, window_started_at, attempts)
  values (p_route_name, 'client-day', p_client_hash, v_now, 1)
  on conflict (route_name, bucket_kind, bucket_hash) do update set
    window_started_at = case
      when current_limit.window_started_at <= v_now - interval '1 day' then v_now
      else current_limit.window_started_at
    end,
    attempts = case
      when current_limit.window_started_at <= v_now - interval '1 day' then 1
      else least(current_limit.attempts + 1, 61)
    end
  returning attempts into v_client_day;

  insert into public.public_endpoint_rate_limits as current_limit
    (route_name, bucket_kind, bucket_hash, window_started_at, attempts)
  values (p_route_name, 'global-day', p_global_hash, v_now, 1)
  on conflict (route_name, bucket_kind, bucket_hash) do update set
    window_started_at = case
      when current_limit.window_started_at <= v_now - interval '1 day' then v_now
      else current_limit.window_started_at
    end,
    attempts = case
      when current_limit.window_started_at <= v_now - interval '1 day' then 1
      else least(current_limit.attempts + 1, 401)
    end
  returning attempts into v_global_day;

  delete from public.public_endpoint_rate_limits
    where window_started_at < v_now - interval '2 days';

  -- 6 requests/minute and 60/day per client; 10/minute and 400/day globally.
  -- The daily ceiling leaves headroom below the documented 1,000 request/day
  -- free-plan limit for openai/gpt-oss-20b, including one correction retry.
  return v_client_minute <= 6
    and v_global_minute <= 10
    and v_client_day <= 60
    and v_global_day <= 400;
end;
$$;

revoke all on function public.consume_public_endpoint_rate_limit(text, text, text)
  from public, anon, authenticated;
grant execute on function public.consume_public_endpoint_rate_limit(text, text, text)
  to service_role;
